  @spec var candidate: Cabin_Air_Quality_Humidity_Supervisor.QualifiedPreferenceCandidate = $

  def get_candidate() : Option[Cabin_Air_Quality_Humidity_Supervisor.QualifiedPreferenceCandidate] = {
    Contract(
      Ensures(
        Res == Some(candidate)
      )
    )
    val value : Option[Cabin_Air_Quality_Humidity_Supervisor.QualifiedPreferenceCandidate] = Art.getValue(candidate_Id) match {
      case Some(Cabin_Air_Quality_Humidity_Supervisor.QualifiedPreferenceCandidate_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port candidate.  Expecting 'Cabin_Air_Quality_Humidity_Supervisor.QualifiedPreferenceCandidate_Payload' but received ${v}")
